#pragma once

#include <AK/Span.h>
#include <Kernel/Boot/Exile/BootGuardian.h>

namespace Kernel {

// Trust anchors compiled into the prekernel. Generated by CMake from BOOT_TRUST_ANCHOR_PUBKEY.
ReadonlySpan<Exile::Boot::TrustAnchor> boot_trust_anchors();

// Verifies the kernel image embedded in this prekernel against the signed boot manifest embedded next to it.
// Panics, and therefore never returns control to the boot sequence, unless verification succeeds.
// Must be called on the pristine image, before it is mapped or relocated.
void verify_kernel_image_or_panic(ReadonlyBytes kernel_image);

}
